const cards = () => M.cards, byId = id => M.byId[id];
const PLACEHOLDER = 'data:image/svg+xml;utf8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="6" fill="#e8e4de"/><path d="M10 28l7-9 5 6 4-4 4 7z" fill="#b8b3a8"/></svg>');
const THUMB = c => c.picture || PLACEHOLDER;
const vendorCards = v => cards().filter(c => c.vendor === v);
