function setQty(id, v) { const c = byId(id); if (!c || !c.inCart) return; const n = parseInt(v, 10); v = Number.isFinite(n) ? Math.max(1, n) : c.suggested; if (v === c.inCart.qty) { render(); return; } act(() => api.setCartQty(id, v)); }
