function undoOrder(v) { const r = L.receipts[v]; if (!r) return; act(async () => { for (const [id, qty] of r.restore) await api.addToCart({ cardId: id, qty, addedBy: 'desk' }); r.orderIds.forEach(id => L.undone[id] = true); r.open.forEach(id => { delete L.backorder[id]; }); delete L.receipts[v]; saveL(); }, ES() ? 'Pedido deshecho — las tarjetas volvieron' : 'Order undone — the cards are back'); }
function closeReceipt(v) { const r = L.receipts[v]; if (r && !r.open.length) { r.receivedAt = M.today; r.closed = true; } }
function receiveOrder(v) { const r = L.receipts[v]; if (!r) return; r.open.forEach(id => { L.received[id] = M.today; }); r.open = []; closeReceipt(v); saveL(); render(); toast(`${t('received')} — ${v}`); }
function receiveItem(id) { const v = orderedMap(L.receipts)[id]; if (!v) return; const r = L.receipts[v]; r.open = r.open.filter(x => x !== id); L.received[id] = M.today; closeReceipt(v); saveL(); render(); toast(`${t('received')} — ${shortName(byId(id))}${!r.open.length ? ` · ${ES() ? 'pedido completo' : 'order complete'} · ${v}` : ''}`); }
