  let h = `<p class="muted" style="margin:0 0 6px;font-size:14px">${es ? 'Recorre el estante en este orden y agrega lo que esté por debajo de su nivel.' : 'Walk the shelf in this order and add anything below its level.'}</p>`;
  if (flagged.length) h += `<div class="eyebrow" style="margin-top:8px"><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--c);margin-right:6px"></i>${es ? 'MARCADAS' : 'FLAGGED'} · ${flagged.length}</div>` + flagged.map(row).join('');
  h += `<div class="eyebrow" style="margin-top:12px">${es ? 'RESTO DEL ESTANTE' : 'REST OF THE SHELF'} · ${rest.length}</div>`; let zone = null; rest.forEach(c => { if (c.zone !== zone) { zone = c.zone; h += `<div class="eyebrow" style="margin-top:10px;color:var(--ink-2)">${esc(zone)}</div>`; } h += row(c); });
