function qrSvg(text) { try { if (typeof window.qrcode === 'function') { const q = window.qrcode(0, 'M'); q.addData(text); q.make(); return q.createSvgTag({ cellSize: 4, margin: 0, scalable: true }); } } catch (e) { console.warn('qr', e); } return `<svg viewBox="0 0 29 29" xmlns="http://www.w3.org/2000/svg"><rect width="29" height="29" fill="#fff"/><text x="2" y="16" font-size="5">QR</text></svg>`; }
const tagUrl = (c, red) => `${PAGE_URL}?flag=${c.id}${red ? '&red=1' : ''}`;
